using System.ComponentModel;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class Tools
{
    [McpServerTool, Description("Echoes the input message back with a timestamp.")]
    public static string Echo(
        [Description("The message to echo")] string message)
    {
        return $"[{DateTime.UtcNow:O}] {message}";
    }

    [McpServerTool, Description("Adds two numbers together.")]
    public static double Add(
        [Description("First number")] double a,
        [Description("Second number")] double b)
    {
        return a + b;
    }
}

using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerResourceType]
public static class Resources
{
    [McpServerResource(UriTemplate = "config://app", Name = "App Configuration",
        MimeType = "application/json"),
     Description("Returns the current application configuration as JSON.")]
    public static string GetAppConfig()
    {
        var config = new
        {
            environment = "production",
            version = "1.0.0",
            features = new
            {
                caching = true,
                rateLimit = 100,
                maxPayloadSizeKb = 512
            },
            endpoints = new[]
            {
                new { name = "api", url = "https://api.example.com" },
                new { name = "auth", url = "https://auth.example.com" }
            }
        };

        return JsonSerializer.Serialize(config, new JsonSerializerOptions { WriteIndented = true });
    }

    [McpServerResource(UriTemplate = "config://features/{featureName}", Name = "Feature Flag",
        MimeType = "application/json"),
     Description("Returns the status of a specific feature flag.")]
    public static string GetFeatureFlag(
        [Description("Name of the feature flag to check")] string featureName)
    {
        var flags = new Dictionary<string, bool>(StringComparer.OrdinalIgnoreCase)
        {
            ["caching"] = true,
            ["rateLimit"] = true,
            ["darkMode"] = false,
            ["betaAccess"] = false
        };

        var enabled = flags.TryGetValue(featureName, out var value) && value;

        return JsonSerializer.Serialize(new { feature = featureName, enabled });
    }
}

